<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Balloon Pop Archery</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #000; }
  canvas { display: block; cursor: crosshair; }
  #overlay {
    position: fixed; inset: 0; display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    background: rgba(0,0,0,0.75); z-index: 10;
    font-family: 'Press Start 2P', monospace; color: #fff;
  }
  #overlay h1 { font-size: 28px; color: #ffd700; text-shadow: 3px 3px 0 #b8860b; margin-bottom: 24px; }
  #overlay p { font-size: 11px; margin: 6px 0; color: #ccc; }
  #overlay .big { font-size: 16px; color: #fff; }
  #overlay button {
    margin-top: 28px; font-family: 'Press Start 2P', monospace;
    font-size: 14px; padding: 14px 28px; cursor: pointer;
    background: #ffd700; color: #000; border: 4px solid #fff;
    box-shadow: 0 6px 0 #b8860b;
  }
  #overlay button:hover { background: #ffe44d; }
  #overlay button:active { transform: translateY(3px); box-shadow: 0 3px 0 #b8860b; }
  .hidden { display: none !important; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="overlay">
  <h1>🏹 BALLOON POP</h1>
  <p class="big" id="ov-msg">Aim with mouse. Hold to draw, release to fire.</p>
  <p>Pop 10 balloons to win. 5 misses and you lose!</p>
  <button id="btn">START</button>
</div>
